import React, { useEffect, useState } from 'react';
import { Button, Drawer, Form, Input, Space, Switch, Table, Tag, message } from 'antd';
import { ReloadOutlined, SettingOutlined } from '@ant-design/icons';

const APPLICATION_ID = '01a0d95f-0701-7c40-8078-164e95a5663e';
const APPLICATION_PATH = '/api/console/applications/{id}';
const ORCHESTRATION_PATH = APPLICATION_PATH + '/orchestration';
const SCHEDULE_PATH = '/api/console/applications/{application_id}/workflow-schedule-trigger';
const DATE_SUFFIX = '触发时间（UTC）：{{trigger.scheduled_at}}';
const clone = value => JSON.parse(JSON.stringify(value));

export default function DailyTaskManager({ ctx }) {
  const { t } = ctx.i18n;
  const locale = ctx.i18n.locale.replace("_", "-");
  const [row, setRow] = useState(null);
  const [document, setDocument] = useState(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [running, setRunning] = useState(false);
  const [queueOpen, setQueueOpen] = useState(false);
  const [queueLoading, setQueueLoading] = useState(false);
  const [queueRuns, setQueueRuns] = useState([]);
  const [toggling, setToggling] = useState(false);
  const [open, setOpen] = useState(false);
  const [form] = Form.useForm();

  async function load() {
    setLoading(true);
    try {
      const [application, orchestration, schedule] = await Promise.all([
        ctx.api.get(APPLICATION_PATH, { path: { id: APPLICATION_ID } }),
        ctx.api.get(ORCHESTRATION_PATH, { path: { id: APPLICATION_ID } }),
        ctx.api.get(SCHEDULE_PATH, { path: { application_id: APPLICATION_ID } })
      ]);
      const doc = orchestration.draft.document;
      const llm = doc.graph.nodes.find(node => node.type === 'llm');
      if (!llm) throw new Error(t("The workflow has no LLM node"));
      const prompts = llm.bindings.prompt_messages.value;
      const system_prompt = prompts.find(item => item.role === 'system')?.content?.value || '';
      const userPrompt = prompts.find(item => item.role === 'user')?.content?.value || '';
      const task = userPrompt.endsWith(DATE_SUFFIX) ? userPrompt.slice(0, -DATE_SUFFIX.length).trim() : userPrompt;
      const cron = schedule.cron || '0 1 * * *';
      const parts = cron.split(' ');
      setDocument(doc);
      setRow({ id: application.id, name: application.name, model: llm.config.model_provider.model_id, time: parts.length === 5 ? parts[1].padStart(2, '0') + ':' + parts[0].padStart(2, '0') : cron, enabled: schedule.enabled, system_prompt, task });
    } catch (error) {
      message.error(t(error?.message || t("Unable to load scheduled tasks")));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { load(); }, []);
  useEffect(() => { if (open && row) form.setFieldsValue({ time: row.time, system_prompt: row.system_prompt, task: row.task }); }, [open, row]);

  function edit() {
    if (!row) return;
    setOpen(true);
  }

  async function save() {
    try {
      const values = await form.validateFields();
      if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(values.time)) throw new Error(t("Please enter a valid 24-hour time"));
      setSaving(true);
      const doc = clone(document);
      const llm = doc.graph.nodes.find(node => node.type === 'llm');
      const prompts = llm.bindings.prompt_messages.value;
      prompts.find(item => item.role === 'system').content.value = values.system_prompt.trim();
      prompts.find(item => item.role === 'user').content.value = values.task.trim() + '\n' + DATE_SUFFIX;
      const [hour, minute] = values.time.split(':').map(Number);
      await ctx.api.put(ORCHESTRATION_PATH + '/draft', { path: { id: APPLICATION_ID }, body: { document: doc, change_kind: 'logical', summary: '更新日报任务提示词' } });
      await ctx.api.post('/api/console/applications/{application_id}/api-publications', { path: { application_id: APPLICATION_ID }, body: { api_enabled: false, mapping: { extension: null, input: { query_target: 'node-workflow-start.query' }, output: { answer_selector: null } } } });
      await ctx.api.put(SCHEDULE_PATH, { path: { application_id: APPLICATION_ID }, body: { cron: minute + ' ' + hour + ' * * *', timezone: 'Asia/Shanghai', input_payload: {}, enabled: row.enabled } });
      message.success(t("The scheduled task has been saved"));
      setOpen(false);
      await load();
    } catch (error) {
      if (!error?.errorFields) message.error(t(error?.message || t("Unable to save the scheduled task")));
    } finally {
      setSaving(false);
    }
  }

  async function toggle(nextEnabled) {
    if (!row || toggling) return;
    setToggling(true);
    try {
      const [hour, minute] = row.time.split(':').map(Number);
      await ctx.api.put(SCHEDULE_PATH, { path: { application_id: APPLICATION_ID }, body: { cron: minute + ' ' + hour + ' * * *', timezone: 'Asia/Shanghai', input_payload: {}, enabled: nextEnabled } });
      setRow(current => current ? { ...current, enabled: nextEnabled } : current);
      message.success(nextEnabled ? t("The task has been enabled") : t("The task has been disabled"));
      await load();
    } catch (error) {
      message.error(t(error?.message || t("Unable to change the task status")));
    } finally {
      setToggling(false);
    }
  }

  async function runNow() {
    if (!row || running) return;
    setRunning(true);
    try {
      const runDocument = clone(document);
      const prompt = runDocument.graph.nodes.find(node => node.type === 'llm').bindings.prompt_messages.value.find(item => item.role === 'user');
      prompt.content.value = prompt.content.value.replace('{{trigger.scheduled_at}}', new Date().toISOString());
      const started = await ctx.api.post('/api/console/applications/{id}/orchestration/debug-runs', {
        path: { id: APPLICATION_ID },
        body: { input_payload: {}, document: runDocument }
      });
      if (!started.run?.id) throw new Error(t("The manual run did not return a run ID"));
      message.success(t("The daily report task has been submitted. Check the queue for its status."));
    } catch (error) {
      message.error(t(error?.message || t("The manual run failed")));
    } finally {
      setRunning(false);
    }
  }

  async function loadQueue() {
    setQueueLoading(true);
    try {
      const page = await ctx.api.get('/api/console/applications/{id}/logs/runs', {
        path: { id: APPLICATION_ID },
        query: { page: 1, page_size: 100, sort_by: 'created_at', sort_order: 'desc', cache_mode: 'refresh' }
      });
      setQueueRuns(page.items || []);
    } catch (error) {
      message.error(t(error?.message || t("Unable to load the run queue")));
    } finally {
      setQueueLoading(false);
    }
  }

  function openQueue() {
    setQueueOpen(true);
    void loadQueue();
  }

  const statusLabels = { queued: t("Queued"), pending: t("Pending"), running: t("Running"), succeeded: t("Completed"), failed: t("Failed"), cancelled: t("Cancelled"), canceled: t("Cancelled") };
  const statusColors = { queued: 'blue', pending: 'blue', running: 'processing', succeeded: 'success', failed: 'error', cancelled: 'default', canceled: 'default' };
  const formatRunTime = value => value ? new Date(value).toLocaleString(locale, { timeZone: 'Asia/Shanghai', hour12: false }) : '—';

  const columns = [
    { title: t("Task"), dataIndex: 'name', key: 'name' },
    { title: t("Run time"), dataIndex: 'time', key: 'time', render: value => t("Every day at {{time}} (Beijing time)", { values: { time: value } }) },
    { title: t("Model"), dataIndex: 'model', key: 'model' },
    { title: t("Enabled"), dataIndex: 'enabled', key: 'enabled', render: value => <Switch checked={Boolean(value)} loading={toggling} disabled={loading || saving} onChange={toggle} checkedChildren={t("On")} unCheckedChildren={t("Off")} aria-label={t("Enable scheduled task")} /> },
    { title: t("Actions"), key: 'actions', render: () => <Space><Button type="link" loading={running} onClick={runNow}>{t("Run now")}</Button><Button type="link" onClick={openQueue}>{t("Queue")}</Button><Button type="link" onClick={edit}>{t("Edit")}</Button></Space> }
  ];

  return <div style={{ padding: 24 }}>
    <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 16 }}>
      <Button icon={<ReloadOutlined />} loading={loading} onClick={load}>{t("Refresh")}</Button>
    </div>
    <Table rowKey="id" dataSource={row ? [row] : []} columns={columns} loading={loading} pagination={false} scroll={{ x: 800 }} />
    <Drawer title={t("Run queue (last 100 runs)")} open={queueOpen} size="min(760px, calc(100vw - 16px))" onClose={() => setQueueOpen(false)} extra={<Button icon={<ReloadOutlined />} loading={queueLoading} onClick={loadQueue}>{t("Refresh")}</Button>}>
      <Table rowKey="id" dataSource={queueRuns} loading={queueLoading} pagination={{ pageSize: 10 }} scroll={{ x: 560 }} columns={[
        { title: t("Triggered at (Beijing time)"), dataIndex: 'started_at', key: 'started_at', render: formatRunTime },
        { title: t("Mode"), dataIndex: 'run_mode', key: 'run_mode', render: value => value === 'workflow_schedule_run' ? t("Scheduled") : value === 'debug_flow_run' ? t("Manual") : value },
        { title: t("Status"), dataIndex: 'status', key: 'status', render: value => <Tag color={statusColors[value] || 'default'}>{statusLabels[value] || value}</Tag> }
      ]} />
    </Drawer>
    <Drawer title={t("Edit daily report schedule")} open={open} size="min(680px, calc(100vw - 16px))" destroyOnHidden onClose={() => setOpen(false)} extra={<Space><Button onClick={() => setOpen(false)}>{t("Cancel")}</Button><Button type="primary" loading={saving} icon={<SettingOutlined />} onClick={save}>{t("Save")}</Button></Space>}>
      <Form form={form} layout="vertical">
        <Form.Item name="time" label={t("Daily run time (Beijing time)")} rules={[{ required: true, message: t("Please select a run time") }]}><Input type="time" /></Form.Item>
        <Form.Item name="system_prompt" label={t("LLM system prompt")} rules={[{ required: true, whitespace: true, message: t("Please enter a system prompt") }]}><Input.TextArea rows={9} /></Form.Item>
        <Form.Item name="task" label={t("Task")} rules={[{ required: true, whitespace: true, message: t("Please enter a task") }]}><Input.TextArea rows={4} /></Form.Item>
      </Form>
    </Drawer>
  </div>;
}
